"eg__b\">' +\r\n      (params ? '<div class=\"prms\">' + params + \"</div>\" : '<div class=\"min\">No parameters.</div>') +\r\n      (e.body ? '<div class=\"prm\"><label>Request body</label><textarea data-body>' + esc(e.body) + \"</textarea></div>\" : \"\") +\r\n      '<div><button class=\"btn btn--ghost\" data-run type=\"button\">Send request</button>' +\r\n      (e.admin ? ' <span class=\"min\" style=\"color:var(--accent)\">needs admin key above</span>' : \"\") + \"</div>\" +\r\n      '<div class=\"resp\"><pre data-out>Not sent yet.</pre></div>' +\r\n      \"</div></div>\";\r\n  });\r\n\r\n  host.addEventListener(\"click\", function (ev) {\r\n    var eg = ev.target.closest(\".eg\");\r\n    if (!eg) return;\r\n    if (ev.target.closest(\"[data-run]\")) return send(eg);\r\n    if (ev.target.closest(\".eg__h\")) eg.dataset.open = eg.dataset.open === \"true\" ? \"false\" : \"true\";\r\n  });\r\n\r\n  $(\"#aExpand\").addEventListener(\"click\", function () {\r\n    var open = Array.prototype.some.call(host.querySelectorAll(\".eg\"), function (e) { return e.dataset.open !== \"true\"; });\r\n    Array.prototype.forEach.call(host.querySelectorAll(\".eg\"), function (e) { e.dataset.open = open ? \"true\" : \"false\"; });\r\n  });\r\n  $(\"#aKey\").addEventListener(\"input\", function () { adminKey = this.value; });\r\n\r\n  function send(eg) {\r\n    var def = ENDPOINTS[+eg.id.slice(2)];\r\n    if (!def) return;\r\n    var path = def.p, query = {};\r\n    Array.prototype.forEach.call(eg.querySelectorAll(\"[data-p]\"), function (inp) {\r\n      var k = inp.dataset.p;\r\n      if (k === def.pv) path = path.replace(\":\" + k, encodeURIComponent(inp.value));\r\n      else query[k] = inp.value;\r\n    });\r\n    var body = null, ta = eg.querySelector(\"[data-body]\");\r\n    if (ta) { try { body = JSON.parse(ta.value); } catch (e) { var o = eg.querySelector(\"[data-out]\"); o.innerHTML = '<span class=\"st st--4\">body</span>Request body is not valid JSON.'; return; } }\r\n    var out = eg.querySelector(\"[data-out]\");\r\n    out.textContent = \"Sending…\";\r\n    api(path, { method: def.m, query: query, body: body, admin: def.admin }).then(function (r) {\r\n      var cls = r.status >= 500 ? \"st--5\" : r.status >= 400 ? \"st--4\" : \"st--2\";\r\n      var txt = r.json ? JSON.stringify(r.json, null, 2) : r.text;\r\n      if (txt && txt.length > 60000) txt = txt.slice(0, 60000) + \"\\n… truncated\";\r\n      out.innerHTML = '<span class=\"st ' + cls + '\">' + r.status + \" \" + (r.status === 0 ? \"no response\" : r.ok ? \"ok\" : \"error\") + \"</span>\" +\r\n        '<span style=\"color:var(--faint)\">' + esc(r.url) + \"</span>\\n\" + esc(txt);\r\n    });\r\n  }\r\n}\r\n\r\n/* ============================ settings ============================ */\r\nvar dlg = $(\"#cfg\");\r\nfunction openCfg() { $(\"#cfgBase\").value = base; $(\"#cfgMsg\").textContent = \"\"; if (dlg.showModal) dlg.showModal(); else dlg.setAttribute(\"open\", \"\"); }\r\n$(\"#cfgBtn\").addEventListener(\"click\", openCfg);\r\n$(\"#baseChip\").addEventListener(\"click\", openCfg);\r\n$(\"#cfgTest\").addEventListener(\"click\", function () {\r\n  var v = $(\"#cfgBase\").value.trim().replace(/\\/+$/, \"\");\r\n  $(\"#cfgMsg\").innerHTML = '<span class=\"spin\"></span> Testing';\r\n  fetch(v.replace(/\\/+$/, \"\") + \"/health\").then(function (r) { return r.text().then(function (t) {\r\n    var ok = r.ok;\r\n    $(\"#cfgMsg\").innerHTML = ok\r\n      ? '<span class=\"ok-note\">Reachable · HTTP ' + r.status + \"</span>\"\r\n      : '<span style=\"color:var(--bad)\">HTTP ' + r.status + \" · \" + esc(t.slice(0, 120)) + \"</span>\";\r\n  }); }).catch(function (e) { $(\"#cfgMsg\").innerHTML = '<span style=\"color:var(--bad)\">' + esc(String(e.message || e)) + \"</span>\"; });\r\n});\r\n$(\"#cfgSave\").addEventListener(\"click\", function () {\r\n  var v = $(\"#cfgBase\").value.trim().replace(/\\/+$/, \"\");\r\n  if (!v) return;\r\n  base = v;\r\n  try { localStorage.setItem(LS, v); } catch (e) {}\r\n  if (dlg.close) dlg.close(); else dlg.removeAttribute(\"open\");\r\n  paintBase();\r\n  health();\r\n  loadRoutes();\r\n});\r\n\r\n/* ============================ boot ============================ */\r\nfunction paintBase() {\r\n  var el = $(\"#baseChip\");\r\n  if (!el) return;\r\n  var host = base;\r\n  try { host = new URL(base).host; } catch (e) {}\r\n  el.textContent = \"api: \" + host;\r\n}\r\nresolveBase().then(function (b) {\r\n  base = b;\r\n  paintBase();\r\n  health();\r\n  loadRoutes();\r\n});\r\nsetInterval(health, 30000);\r\n</script>\r\n</body>\r\n</html>\r\n";
